// READ ONLY. Picks the ResumeWise frontend project and builds a count URL.
const CFG = { name_match: /resume/i, exclude: /(back|email|html|legal)/i, filter_tags: 'to_review' };
const r = $input.first().json;
const body = r.body || r;
if (!Array.isArray(body.projects)) { throw new Error('projects list missing: ' + JSON.stringify(body).slice(0,300)); }
const cands = body.projects.filter(p => CFG.name_match.test(p.name)).map(p => ({ id: p.project_id, name: p.name, keys_total: p.statistics && p.statistics.keys_total }));
const chosen = cands.filter(c => !CFG.exclude.test(c.name));
if (chosen.length !== 1) { throw new Error('Expected exactly 1 frontend candidate, got: ' + JSON.stringify(cands)); }
const pid = chosen[0].id;
const url = 'https://api.lokalise.com/api2/projects/' + pid + '/keys?limit=1&page=1&filter_tags=' + encodeURIComponent(CFG.filter_tags);
return [{ json: { project_id: pid, project_name: chosen[0].name, candidates: cands, projects_seen: body.projects.length, total_header: (r.headers||{})['x-pagination-total-count'] || null, filter_tags: CFG.filter_tags, url } }];

const cfg = $('Pick Project').first().json;
const r = $input.first().json;
const body = r.body || r;
if (!Array.isArray(body.keys)) { throw new Error('count call returned no keys array: ' + JSON.stringify(body).slice(0,300)); }
const total = Number((r.headers||{})['x-pagination-total-count'] || 0);
const LIMIT = 500;
const pages = Math.max(1, Math.ceil(total / LIMIT));
const out = [];
for (let i = 1; i <= pages; i++) {
  out.push({ json: { page: i, total, url: 'https://api.lokalise.com/api2/projects/' + cfg.project_id + '/keys?include_translations=1&disable_references=1&limit=' + LIMIT + '&page=' + i + '&filter_tags=' + encodeURIComponent(cfg.filter_tags) } });
}
return out;

const cfg = $('Pick Project').first().json;
const total = $('Expand Pages').first().json.total;
const PSEUDO = new Set(['pst','ps','cus','pt_old']);
const rows = []; const errors = []; let keysSeen = 0; const langs = {};
for (const p of $input.all()) {
  const r = p.json || {}; const body = r.body || r;
  if (!Array.isArray(body.keys)) { errors.push({ statusCode: r.statusCode, body: JSON.stringify(body).slice(0,300) }); continue; }
  for (const key of body.keys) {
    keysSeen++;
    const tr = Array.isArray(key.translations) ? key.translations : [];
    const name = typeof key.key_name === 'object' ? (key.key_name.web || key.key_name.other || '') : key.key_name;
    const enT = tr.find(t => t.language_iso === 'en');
    const str = v => (v === null || v === undefined) ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
    const en = enT ? str(enT.translation) : '';
    if (!en) continue;
    const t = {}; const m = {};
    for (const x of tr) {
      const iso = x.language_iso;
      if (iso === 'en' || PSEUDO.has(iso)) continue;
      const v = str(x.translation);
      if (!v) continue;
      t[iso] = v; m[iso] = (x.modified_at || '') + '|' + (x.is_reviewed ? 1 : 0) + '|' + (x.is_unverified ? 1 : 0);
      langs[iso] = (langs[iso] || 0) + 1;
    }
    rows.push({ k: name, en, t, m, tags: key.tags || [], d: key.description || '' });
  }
}
return [{ json: { mode: 'keys', project_id: cfg.project_id, project_name: cfg.project_name, candidates: cfg.candidates, filter_tags: cfg.filter_tags, server_total: total, keys_seen: keysSeen, rows_kept: rows.length, langs, errors, rows } }];
